CREATE TABLE connection_profiles(instance_uid TEXT PRIMARY KEY REFERENCES instances, config TEXT NOT NULL, verified_at REAL);
CREATE TABLE collection_configs(project_uid TEXT PRIMARY KEY REFERENCES projects, embedding_fields TEXT NOT NULL);
CREATE TABLE collection_snapshots(job_id TEXT PRIMARY KEY REFERENCES jobs(job_id), config_revision TEXT NOT NULL, snapshot TEXT NOT NULL);
CREATE TABLE collection_outcomes(job_id TEXT NOT NULL REFERENCES jobs(job_id), source_item_id TEXT NOT NULL, item_uid TEXT REFERENCES items, revision_uid TEXT REFERENCES item_revisions, state TEXT NOT NULL CHECK(state IN ('SUCCEEDED','FAILED','SKIPPED')), error_code TEXT, PRIMARY KEY(job_id,source_item_id));
CREATE TABLE collection_failures(job_id TEXT NOT NULL REFERENCES jobs(job_id), source_item_id TEXT NOT NULL, project_uid TEXT NOT NULL REFERENCES projects, item_uid TEXT REFERENCES items, revision_uid TEXT REFERENCES item_revisions, error_code TEXT NOT NULL, retryable INTEGER NOT NULL DEFAULT 1 CHECK(retryable IN (0,1)), attempts INTEGER NOT NULL DEFAULT 1, replay_state TEXT NOT NULL DEFAULT 'PENDING', PRIMARY KEY(job_id,source_item_id));
CREATE TABLE collection_memberships(project_uid TEXT NOT NULL REFERENCES projects, source_item_id TEXT NOT NULL, scope_id TEXT, state TEXT NOT NULL CHECK(state IN ('IN_SCOPE','OUT_OF_SCOPE','MISSING','UNAUTHORIZED','DELETED')), last_job_id TEXT NOT NULL REFERENCES jobs(job_id), PRIMARY KEY(project_uid,source_item_id));
CREATE TABLE item_collection_state(item_uid TEXT PRIMARY KEY REFERENCES items, latest_revision_uid TEXT NOT NULL, last_job_id TEXT NOT NULL REFERENCES jobs(job_id), FOREIGN KEY(latest_revision_uid,item_uid) REFERENCES item_revisions(revision_uid,item_uid));
